response_body.text:
:root {
  color-scheme: light;
  --ink: #16222e;
  --muted: #5d7185;
  --line: #dbe4ee;
  --paper: #ffffff;
  --bg: #eef3fa;
  --accent: #1f6feb;
  --accent-soft: #e8f0fe;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html,
body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  font-family: "PingFang SC", "Microsoft YaHei", "Noto Sans SC",
    system-ui, -apple-system, "Segoe UI", sans-serif;
  color: var(--ink);
  background: var(--bg);
  -webkit-text-size-adjust: 100%;
}

/* 三块结构：顶部标题、左侧菜单、右侧内容 */
.layout {
  display: grid;
  grid-template-rows: auto 1fr;
  min-height: 100vh;
  min-width: 0;
}

.topbar {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px 14px;
  padding: 22px 28px;
  background: var(--paper);
  border-bottom: 1px solid var(--line);
}

.topbar h1 {
  margin: 0;
  font-size: 24px;
  line-height: 1.35;
  letter-spacing: 0.01em;
  overflow-wrap: anywhere;
}

.topbar .tag {
  margin: 0;
  font-size: 14px;
  color: var(--muted);
}

.body {
  display: flex;
  align-items: stretch;
  min-width: 0;
}

/* 左侧菜单 */
.sidebar {
  flex: 0 0 208px;
  background: var(--paper);
  border-right: 1px solid var(--line);
  padding: 16px 12px;
  min-width: 0;
}

.menu {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.menu-item {
  display: flex;
  align-items: center;
  width: 100%;
  min-height: 44px;
  padding: 0 14px;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: 15px;
  line-height: 1.4;
  text-align: left;
  cursor: pointer;
  white-space: nowrap;
}

.menu-item:hover {
  background: #f1f5fb;
}

.menu-item:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: -2px;
}

.menu-item[aria-current="page"] {
  background: var(--accent-soft);
  color: var(--accent);
  font-weight: 600;
}

/* 右侧内容 */
.content {
  flex: 1 1 auto;
  min-width: 0;
  padding: 28px;
}

.panel {
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 28px 30px;
}

.panel h2 {
  margin: 0 0 12px;
  font-size: 22px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.panel p {
  margin: 0;
  font-size: 15px;
  line-height: 1.8;
  color: var(--muted);
  overflow-wrap: anywhere;
}

/* 概览统计卡片：宽屏并排，窄屏自动换行 */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 14px;
  margin: 22px 0 0;
  padding: 0;
  list-style: none;
}

.cards > li {
  min-width: 0;
}

.card {
  min-width: 0;
  padding: 18px 20px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fafcff;
}

.card-button {
  display: block;
  width: 100%;
  text-align: left;
  font: inherit;
  color: inherit;
  cursor: pointer;
}

.card-button:hover {
  border-color: #b9cde4;
  background: #f5f9ff;
}

.card-button:hover .card-value {
  color: var(--accent);
}

.card-button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.card-label {
  display: block;
  margin: 0 0 10px;
  font-size: 14px;
  line-height: 1.5;
  color: var(--muted);
}

.card-value {
  display: block;
  margin: 0;
  font-size: 22px;
  line-height: 1.4;
  font-weight: 600;
  color: var(--ink);
  overflow-wrap: anywhere;
}

.next-up {
  margin-top: 22px;
  padding: 18px 20px;
  border: 1px dashed #c3d4e8;
  border-radius: 12px;
  background: #f5f9ff;
}

.next-up h3 {
  margin: 0 0 8px;
  font-size: 16px;
  line-height: 1.5;
}

.next-up p {
  margin: 0;
  font-size: 15px;
  line-height: 1.8;
  color: var(--ink);
  overflow-wrap: anywhere;
}

.data-note {
  margin: 18px 0 0;
  font-size: 13px;
  line-height: 1.7;
  color: var(--muted);
  overflow-wrap: anywhere;
}

/* 空间卡片：宽屏并排，窄屏自动换行 */
.space-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 14px;
  margin-top: 20px;
}

.space-card {
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-width: 0;
  padding: 18px 20px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fafcff;
}

.space-card h3 {
  margin: 0;
  font-size: 17px;
  line-height: 1.4;
  overflow-wrap: anywhere;
}

.space-facts {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  gap: 6px 14px;
  margin: 0;
}

.space-facts dt {
  font-size: 13px;
  line-height: 1.6;
  color: var(--muted);
}

.space-facts dd {
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
  color: var(--ink);
  overflow-wrap: anywhere;
}

.space-card .space-count {
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
  font-weight: 600;
  color: var(--ink);
}

.space-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: auto;
}

.space-action {
  align-self: flex-start;
  min-height: 36px;
  padding: 0 14px;
  border: 1px solid #c9d8e9;
  border-radius: 8px;
  background: var(--paper);
  color: var(--accent);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}

.space-action:hover {
  background: var(--accent-soft);
}

.space-action.is-secondary {
  background: #f5f9ff;
  color: var(--ink);
}

.space-action.is-secondary:hover {
  background: #eaf1fb;
}

.space-action:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

/* 空间位置编辑表单 */
.space-form {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-top: 12px;
  border-top: 1px dashed var(--line);
}

.space-card .space-form-name {
  margin: 0;
  font-size: 14px;
  line-height: 1.6;
  font-weight: 600;
  color: var(--ink);
  overflow-wrap: anywhere;
}

.space-form-field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.space-form-label {
  font-size: 13px;
  line-height: 1.5;
  color: var(--muted);
}

.space-card .space-form-error {
  margin: 0;
  padding: 8px 10px;
  border: 1px solid #e3b4ae;
  border-radius: 8px;
  background: #fff8f7;
  color: #b42318;
  font-size: 13px;
  line-height: 1.6;
  overflow-wrap: anywhere;
}

.space-form-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.space-save,
.space-cancel {
  min-height: 36px;
  padding: 0 16px;
  border-radius: 8px;
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}

.space-save {
  border: 1px solid var(--accent);
  background: var(--accent);
  color: #ffffff;
}

.space-save:hover {
  background: #1a5fd0;
}

.space-cancel {
  border: 1px solid #c9d8e9;
  background: var(--paper);
  color: var(--ink);
}

.space-cancel:hover {
  background: #eef4fb;
}

.space-save:focus-visible,
.space-cancel:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.space-save:disabled,
.space-cancel:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

/* 设备筛选 */
.filters {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 12px;
}

.filter-field {
  display: flex;
  flex: 1 1 160px;
  flex-direction: column;
  gap: 6px;
  min-width: 0;
}

.filter-field:first-child {
  flex: 2 1 220px;
}

.filter-label {
  font-size: 13px;
  line-height: 1.5;
  color: var(--muted);
}

.filter-control {
  width: 100%;
  min-height: 40px;
  padding: 0 10px;
  border: 1px solid #c9d8e9;
  border-radius: 8px;
  background: var(--paper);
  color: var(--ink);
  font: inherit;
  font-size: 14px;
}

.filter-control:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.clear-button {
  flex: 0 0 auto;
  min-height: 40px;
  padding: 0 16px;
  border: 1px solid #c9d8e9;
  border-radius: 8px;
  background: #f5f9ff;
  color: var(--ink);
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}

.clear-button:hover {
  background: #eaf1fb;
}

.clear-button:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.table-empty {
  margin: 14px 0 0;
  padding: 18px;
  border: 1px dashed var(--line);
  border-radius: 10px;
  text-align: center;
  color: var(--muted);
  font-size: 14px;
}

/* 设备详情 */
.device-detail {
  margin-top: 22px;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: #fafcff;
}

.detail-head {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.detail-head h3 {
  margin: 0;
  font-size: 17px;
  line-height: 1.4;
}

.detail-close {
  min-height: 40px;
  padding: 0 14px;
  border: 1px solid #c9d8e9;
  border-radius: 8px;
  background: var(--paper);
  color: var(--ink);
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}

.detail-close:hover {
  background: #eef4fb;
}

.detail-close:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.detail-facts {
  display: grid;
  grid-template-columns: max-content minmax(0, 1fr);
  gap: 10px 20px;
  margin: 16px 0 0;
}

.detail-facts dt {
  font-size: 13px;
  line-height: 1.6;
  color: var(--muted);
}

.detail-facts dd {
  margin: 0;
  font-size: 15px;
  line-height: 1.6;
  color: var(--ink);
  overflow-wrap: anywhere;
}

.device-detail h4 {
  margin: 20px 0 0;
  font-size: 15px;
  line-height: 1.5;
}

.device-detail .table-wrap {
  margin-top: 10px;
}

.detail-table {
  min-width: 520px;
}

.detail-empty {
  margin-top: 12px;
}

/* 设备表格 */
.table-wrap {
  margin-top: 18px;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.data-table {
  width: 100%;
  min-width: 620px;
  margin-top: 14px;
  border-collapse: collapse;
  font-size: 14px;
}

.data-table th,
.data-table td {
  padding: 10px 12px;
  text-align: left;
  border-bottom: 1px solid var(--line);
  white-space: nowrap;
}

.data-table th {
  background: #f7fafd;
  color: var(--muted);
  font-weight: 600;
}

.data-table tbody tr:hover {
  background: #fafcff;
}

.online-badge {
  display: inline-block;
  padding: 2px 10px;
  border-radius: 999px;
  font-size: 13px;
  line-height: 1.6;
}

.online-badge.is-online {
  background: #e7f6ec;
  color: #157f3b;
}

.online-badge.is-offline {
  background: #fdecea;
  color: #b42318;
}

.online-badge.is-unknown {
  background: #eef2f6;
  color: var(--muted);
}

.row-action {
  min-height: 32px;
  padding: 0 12px;
  border: 1px solid #c9d8e9;
  border-radius: 8px;
  background: var(--paper);
  color: var(--accent);
  font: inherit;
  font-size: 13px;
  cursor: pointer;
}

.row-action:hover {
  background: var(--accent-soft);
}

.table-summary {
  margin: 12px 0 0;
  font-size: 13px;
  line-height: 1.7;
  color: var(--muted);
}

.table-status {
  margin: 16px 0 0;
  font-size: 15px;
  line-height: 1.7;
  color: var(--muted);
}

.table-error {
  margin-top: 16px;
  padding: 16px 18px;
  border: 1px dashed #e3b4ae;
  border-radius: 10px;
  background: #fff8f7;
}

.table-error .table-status {
  margin: 0;
  color: #b42318;
}

.retry-button {
  min-height: 44px;
  margin-top: 12px;
  padding: 0 18px;
  border: 1px solid var(--accent);
  border-radius: 8px;
  background: var(--accent);
  color: #ffffff;
  font: inherit;
  font-size: 14px;
  cursor: pointer;
}

.retry-button:hover {
  background: #1a5fd0;
}

.retry-button:focus-visible,
.row-action:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}

.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
  border: 0;
}

/* 窄屏：菜单改为横向可滚动条，主内容不再被挤出屏幕 */
@media (max-width: 720px) {
  .topbar {
    padding: 18px 18px;
  }

  .topbar h1 {
    font-size: 20px;
  }

  .body {
    flex-direction: column;
  }

  .sidebar {
    flex: 0 0 auto;
    border-right: 0;
    border-bottom: 1px solid var(--line);
    padding: 8px 10px;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
  }

  .menu {
    flex-direction: row;
    gap: 6px;
    width: max-content;
  }

  .menu-item {
    width: auto;
    min-height: 40px;
    padding: 0 12px;
    font-size: 14px;
  }

  .content {
    padding: 16px;
  }

  .panel {
    padding: 20px 18px;
  }

  .panel h2 {
    font-size: 19px;
  }
}

// 校园值班台 · 菜单切换 + 概览/设备/空间数据（第03课第3步）
// 业务数据一律通过 data-service 获取，不直接导入 mock-data，也不请求后端。

import {
  getOverview,
  getDevices,
  getSpaces,
  saveSpace,
} from "./data-service.js";

const VIEWS = [
  { id: "dashboard", title: "概览" },
  { id: "devices", title: "设备" },
  { id: "spaces", title: "空间" },
  { id: "energy", title: "能源" },
  { id: "history", title: "历史" },
  { id: "alarms", title: "原始报警" },
  { id: "cases", title: "演练事件" },
  { id: "owners", title: "设备责任" },
  { id: "admin", title: "管理" },
];

const DEFAULT_VIEW = "dashboard";
const PLACEHOLDER = "这个页面会在后续课程完成";
const DATA_SOURCE_NOTE = "数据方式：浏览器演示（教学模拟）";

const CATEGORY_LABELS = {
  environment: "环境",
  energy: "能源",
  facility: "设施",
  lighting: "照明",
};

const QUALITY_LABELS = {
  fresh: "正常",
  stale: "较旧",
  missing: "缺失",
  invalid: "无效",
};

const menuItems = Array.from(document.querySelectorAll(".menu-item"));
const outlet = document.getElementById("view-outlet");
const sections = new Map();

let devicesView = null;
let devicesLoaded = false;
let devicesLoading = false;
let spacesView = null;
let spacesLoaded = false;
let spacesLoading = false;
let loadedDevices = [];
let loadedSpaces = [];
let loadedPoints = [];
let activeDetailButton = null;
let activeSpaceEditor = null;

const dashboardSection = document.getElementById("view-dashboard");
if (dashboardSection) {
  sections.set(DEFAULT_VIEW, dashboardSection);
}

function createFilterSelect(labelText, options) {
  const label = document.createElement("label");
  label.className = "filter-field";

  const caption = document.createElement("span");
  caption.className = "filter-label";
  caption.textContent = labelText;

  const select = document.createElement("select");
  select.className = "filter-control";

  for (const item of options) {
    const option = document.createElement("option");
    option.value = item.value;
    option.textContent = item.text;
    select.append(option);
  }

  label.append(caption, select);
  return { label, select };
}

// 设备页：标题、筛选、读取状态、表格、设备总数、错误与重试。
function createDevicesSection() {
  const section = document.createElement("section");
  section.className = "panel view";
  section.id = "view-devices";
  section.hidden = true;

  const heading = document.createElement("h2");
  heading.textContent = "设备";

  const status = document.createElement("p");
  status.className = "table-status";
  status.textContent = "正在读取设备";

  const wrap = document.createElement("div");
  wrap.className = "table-wrap";
  wrap.hidden = true;

  const table = document.createElement("table");
  table.className = "data-table";

  const caption = document.createElement("caption");
  caption.className = "visually-hidden";
  caption.textContent = "设备列表";

  const thead = document.createElement("thead");
  const headRow = document.createElement("tr");
  for (const label of ["编号", "设备名称", "类型", "空间", "在线情况", "操作"]) {
    const th = document.createElement("th");
    th.scope = "col";
    th.textContent = label;
    headRow.append(th);
  }
  thead.append(headRow);

  const tbody = document.createElement("tbody");

  table.append(caption, thead, tbody);

  const summary = document.createElement("p");
  summary.className = "table-summary";

  const filters = document.createElement("div");
  filters.className = "filters";
  filters.setAttribute("role", "group");
  filters.setAttribute("aria-label", "设备筛选");

  const searchField = document.createElement("label");
  searchField.className = "filter-field";

  const searchCaption = document.createElement("span");
  searchCaption.className = "filter-label";
  searchCaption.textContent = "搜索";

  const searchInput = document.createElement("input");
  searchInput.type = "search";
  searchInput.className = "filter-control";
  searchInput.placeholder = "名称或编号";
  searchInput.autocomplete = "off";

  searchField.append(searchCaption, searchInput);

  const categoryField = createFilterSelect("类型", [
    { value: "", text: "全部类型" },
    ...Object.entries(CATEGORY_LABELS).map(([value, text]) => ({
      value,
      text,
    })),
  ]);

  const spaceField = createFilterSelect("空间", [
    { value: "", text: "全部空间" },
  ]);

  const onlineField = createFilterSelect("在线情况", [
    { value: "", text: "全部" },
    { value: "true", text: "在线" },
    { value: "false", text: "离线" },
    { value: "null", text: "未知" },
  ]);

  const clearButton = document.createElement("button");
  clearButton.type = "button";
  clearButton.className = "clear-button";
  clearButton.textContent = "清空筛选";

  filters.append(
    searchField,
    categoryField.label,
    spaceField.label,
    onlineField.label,
    clearButton
  );

  const emptyNote = document.createElement("p");
  emptyNote.className = "table-empty";
  emptyNote.textContent = "没有符合条件的设备";
  emptyNote.hidden = true;

  const detail = document.createElement("section");
  detail.className = "device-detail";
  detail.id = "device-detail";
  detail.hidden = true;

  const detailHead = document.createElement("div");
  detailHead.className = "detail-head";

  const detailHeading = document.createElement("h3");
  detailHeading.textContent = "设备详情";

  const closeButton = document.createElement("button");
  closeButton.type = "button";
  closeButton.className = "detail-close";
  closeButton.textContent = "收起详情";

  detailHead.append(detailHeading, closeButton);

  const facts = document.createElement("dl");
  facts.className = "detail-facts";

  const pointsHeading = document.createElement("h4");
  pointsHeading.textContent = "读数";

  const pointsWrap = document.createElement("div");
  pointsWrap.className = "table-wrap";

  const pointsTable = document.createElement("table");
  pointsTable.className = "data-table detail-table";

  const pointsCaption = document.createElement("caption");
  pointsCaption.className = "visually-hidden";
  pointsCaption.textContent = "设备读数";

  const pointsHead = document.createElement("thead");
  const pointsHeadRow = document.createElement("tr");
  for (const label of ["标签", "数值", "单位", "采样时间", "质量"]) {
    const th = document.createElement("th");
    th.scope = "col";
    th.textContent = label;
    pointsHeadRow.append(th);
  }
  pointsHead.append(pointsHeadRow);

  const pointsBody = document.createElement("tbody");

  pointsTable.append(pointsCaption, pointsHead, pointsBody);
  pointsWrap.append(pointsTable);

  const pointsEmpty = document.createElement("p");
  pointsEmpty.className = "table-status detail-empty";
  pointsEmpty.textContent = "该设备暂无读数";
  pointsEmpty.hidden = true;

  detail.append(detailHead, facts, pointsHeading, pointsWrap, pointsEmpty);

  wrap.append(filters, table, emptyNote, summary, detail);

  const errorBox = document.createElement("div");
  errorBox.className = "table-error";
  errorBox.hidden = true;

  const errorText = document.createElement("p");
  errorText.className = "table-status";

  const retryButton = document.createElement("button");
  retryButton.type = "button";
  retryButton.className = "retry-button";
  retryButton.textContent = "重试";

  errorBox.append(errorText, retryButton);

  section.append(heading, status, wrap, errorBox);

  devicesView = {
    section,
    status,
    wrap,
    table,
    tbody,
    emptyNote,
    summary,
    searchInput,
    categorySelect: categoryField.select,
    spaceSelect: spaceField.select,
    onlineSelect: onlineField.select,
    clearButton,
    detail,
    facts,
    pointsTable,
    pointsBody,
    pointsEmpty,
    errorBox,
    errorText,
    retryButton,
  };

  closeButton.addEventListener("click", () => {
    detail.hidden = true;
    if (activeDetailButton) {
      activeDetailButton.setAttribute("aria-expanded", "false");
      activeDetailButton = null;
    }
  });

  searchInput.addEventListener("input", applyDeviceFilters);
  categoryField.select.addEventListener("change", applyDeviceFilters);
  spaceField.select.addEventListener("change", applyDeviceFilters);
  onlineField.select.addEventListener("change", applyDeviceFilters);

  clearButton.addEventListener("click", resetDeviceFilters);

  retryButton.addEventListener("click", () => {
    loadDevices();
  });

  return section;
}

// 空间页：标题、读取状态、四张空间卡片、浏览器演示说明。
function createSpacesSection() {
  const section = document.createElement("section");
  section.className = "panel view";
  section.id = "view-spaces";
  section.hidden = true;

  const heading = document.createElement("h2");
  heading.textContent = "空间";

  const status = document.createElement("p");
  status.className = "table-status";
  status.textContent = "正在读取空间";

  const grid = document.createElement("div");
  grid.className = "space-grid";
  grid.hidden = true;

  const note = document.createElement("p");
  note.className = "data-note";
  note.textContent = "当前浏览器演示，尚未写入数据库";

  const errorBox = document.createElement("div");
  errorBox.className = "table-error";
  errorBox.hidden = true;

  const errorText = document.createElement("p");
  errorText.className = "table-status";

  const retryButton = document.createElement("button");
  retryButton.type = "button";
  retryButton.className = "retry-button";
  retryButton.textContent = "重试";

  errorBox.append(errorText, retryButton);

  section.append(heading, status, grid, note, errorBox);

  spacesView = {
    section,
    status,
    grid,
    note,
    errorBox,
    errorText,
    retryButton,
  };

  retryButton.addEventListener("click", () => {
    loadSpaces();
  });

  return section;
}

// 除概览、设备、空间外，其余页面只显示标题和占位说明；文本一律用 textContent 写入。
for (const view of VIEWS) {
  if (view.id === DEFAULT_VIEW || !outlet) continue;

  let section;

  if (view.id === "devices") {
    section = createDevicesSection();
  } else if (view.id === "spaces") {
    section = createSpacesSection();
  } else {
    section = document.createElement("section");
    section.className = "panel view";
    section.id = `view-${view.id}`;
    section.hidden = true;

    const heading = document.createElement("h2");
    heading.textContent = view.title;

    const note = document.createElement("p");
    note.textContent = PLACEHOLDER;

    section.append(heading, note);
  }

  outlet.append(section);
  sections.set(view.id, section);
}

for (const item of menuItems) {
  const viewId = item.dataset.view;
  if (sections.has(viewId)) {
    item.setAttribute("aria-controls", `view-${viewId}`);
  }
}

function normalizeView(hash) {
  const id = hash.replace(/^#\/?/, "");
  return sections.has(id) ? id : DEFAULT_VIEW;
}

function render(viewId) {
  for (const [id, section] of sections) {
    section.hidden = id !== viewId;
  }

  for (const item of menuItems) {
    if (item.dataset.view === viewId) {
      item.setAttribute("aria-current", "page");
    } else {
      item.removeAttribute("aria-current");
    }
  }

  if (viewId === "devices" && !devicesLoaded) {
    loadDevices();
  }

  if (viewId === "spaces" && !spacesLoaded) {
    loadSpaces();
  }
}

for (const item of menuItems) {
  item.addEventListener("click", () => {
    const viewId = sections.has(item.dataset.view)
      ? item.dataset.view
      : DEFAULT_VIEW;

    render(viewId);

    // 只改地址片段，不发起导航，也不刷新页面。
    if (window.location.hash !== `#${viewId}`) {
      window.location.hash = viewId;
    }
  });
}

// 概览“设备总数”卡片：进入现有设备页，并清空筛选。
const openDevicesCard = document.getElementById("open-devices-card");
if (openDevicesCard) {
  openDevicesCard.addEventListener("click", () => {
    resetDeviceFilters();
    const devicesMenuItem = menuItems.find(
      (item) => item.dataset.view === "devices"
    );
    if (devicesMenuItem) {
      devicesMenuItem.click();
    }
  });
}

window.addEventListener("hashchange", () => {
  render(normalizeView(window.location.hash));
});

const initialView = normalizeView(window.location.hash);
render(initialView);

// 首次进入或片段无效时，用 replaceState 校正地址，不新增历史记录。
if (window.location.hash !== `#${initialView}`) {
  window.history.replaceState(null, "", `#${initialView}`);
}

// ---------- 设备读取 ----------

function setDevicesStatus(text) {
  if (!devicesView) return;
  devicesView.status.textContent = text;
  devicesView.status.hidden = false;
  devicesView.wrap.hidden = true;
  devicesView.errorBox.hidden = true;
}

function showDevicesError(error) {
  if (!devicesView) return;
  const detail =
    error instanceof Error && error.message ? error.message : "未知错误";
  devicesView.status.hidden = true;
  devicesView.wrap.hidden = true;
  devicesView.errorBox.hidden = false;
  devicesView.errorText.textContent = `设备读取失败：${detail}`;
}

function formatOnline(value) {
  if (value === true) return { text: "在线", className: "is-online" };
  if (value === false) return { text: "离线", className: "is-offline" };
  return { text: "未知", className: "is-unknown" };
}

// 设备表同样显示空间位置，空间位置修改后一起更新。
function formatSpaceLabel(space) {
  if (!space) return "未知空间";

  const building =
    typeof space.building === "string" && space.building.trim() !== ""
      ? space.building.trim()
      : "未知楼栋";
  const floor =
    typeof space.floor === "string" && space.floor.trim() !== ""
      ? space.floor.trim()
      : "未知楼层";
  const floorText = floor.endsWith("层") ? floor : `${floor}层`;

  return `${space.name}（${building} ${floorText}）`;
}

function renderDeviceRows(devices, spaces) {
  if (!devicesView) return;

  const spaceLabels = new Map();
  for (const space of spaces) {
    spaceLabels.set(space.id, formatSpaceLabel(space));
  }

  const tbody = devicesView.tbody;
  tbody.replaceChildren();

  for (const device of devices) {
    const row = document.createElement("tr");

    const idCell = document.createElement("td");
    idCell.textContent = device.id;

    const nameCell = document.createElement("td");
    nameCell.textContent = device.name;

    const categoryCell = document.createElement("td");
    categoryCell.textContent = CATEGORY_LABELS[device.category] ?? "未分类";

    const spaceCell = document.createElement("td");
    spaceCell.textContent = spaceLabels.get(device.spaceId) ?? "未知空间";

    const onlineCell = document.createElement("td");
    const online = formatOnline(device.online);
    const badge = document.createElement("span");
    badge.className = `online-badge ${online.className}`;
    badge.textContent = online.text;
    onlineCell.append(badge);

    const actionCell = document.createElement("td");
    const detailButton = document.createElement("button");
    detailButton.type = "button";
    detailButton.className = "row-action";
    detailButton.textContent = "查看";
    detailButton.setAttribute("aria-expanded", "false");
    detailButton.setAttribute("aria-controls", "device-detail");
    detailButton.addEventListener("click", () => {
      openDeviceDetail(device.id, detailButton);
    });
    actionCell.append(detailButton);

    row.append(idCell, nameCell, categoryCell, spaceCell, onlineCell, actionCell);
    tbody.append(row);
  }
}

// ---------- 设备详情 ----------

function formatPointValue(value) {
  if (value === null || value === undefined) return "缺失";
  return String(value);
}

function formatSampleTime(time) {
  if (time === null || time === undefined) return "无采样时间";
  const date = new Date(time);
  if (Number.isNaN(date.getTime())) return "无采样时间";
  return date.toLocaleString("zh-CN", { hour12: false });
}

function renderDetailFacts(device, spaceName) {
  if (!devicesView) return;

  const entries = [
    ["编号", device.id],
    ["名称", device.name],
    ["类型", CATEGORY_LABELS[device.category] ?? "未分类"],
    ["空间", spaceName],
    ["在线情况", formatOnline(device.online).text],
  ];

  const facts = devicesView.facts;
  facts.replaceChildren();

  for (const [label, value] of entries) {
    const term = document.createElement("dt");
    term.textContent = label;

    const description = document.createElement("dd");
    description.textContent = value;

    facts.append(term, description);
  }
}

function renderDetailPoints(points) {
  if (!devicesView) return;

  const tbody = devicesView.pointsBody;
  tbody.replaceChildren();

  for (const point of points) {
    const row = document.createElement("tr");

    const tagCell = document.createElement("td");
    tagCell.textContent = point.tagId;

    const valueCell = document.createElement("td");
    valueCell.textContent = formatPointValue(point.value);

    const unitCell = document.createElement("td");
    unitCell.textContent =
      point.unit === null || point.unit === undefined ? "—" : point.unit;

    const timeCell = document.createElement("td");
    timeCell.textContent = formatSampleTime(point.time);

    const qualityCell = document.createElement("td");
    qualityCell.textContent = QUALITY_LABELS[point.quality] ?? "未知";

    row.append(tagCell, valueCell, unitCell, timeCell, qualityCell);
    tbody.append(row);
  }

  const isEmpty = points.length === 0;
  devicesView.pointsEmpty.hidden = !isEmpty;
  devicesView.pointsTable.hidden = isEmpty;
}

// 按设备原始 id 查找，只显示这一台设备的读数。
function openDeviceDetail(deviceId, triggerButton) {
  if (!devicesView) return;

  const device = loadedDevices.find((item) => item.id === deviceId);
  if (!device) return;

  const space = loadedSpaces.find((item) => item.id === device.spaceId);
  const points = loadedPoints.filter((point) => point.deviceId === device.id);

  renderDetailFacts(device, formatSpaceLabel(space));
  renderDetailPoints(points);

  if (activeDetailButton && activeDetailButton !== triggerButton) {
    activeDetailButton.setAttribute("aria-expanded", "false");
  }
  activeDetailButton = triggerButton;
  triggerButton.setAttribute("aria-expanded", "true");

  devicesView.detail.hidden = false;
}

function matchesOnline(device, filter) {
  if (filter === "") return true;
  if (filter === "true") return device.online === true;
  if (filter === "false") return device.online === false;
  return device.online === null;
}

// 多个条件同时生效；总数与当前数量都按已读取的数组计算。
function applyDeviceFilters() {
  if (!devicesView) return;

  const keyword = devicesView.searchInput.value.trim().toLowerCase();
  const category = devicesView.categorySelect.value;
  const spaceId = devicesView.spaceSelect.value;
  const online = devicesView.onlineSelect.value;

  const filtered = loadedDevices.filter((device) => {
    if (keyword !== "") {
      const haystack = `${device.id} ${device.name}`.toLowerCase();
      if (!haystack.includes(keyword)) return false;
    }
    if (category !== "" && device.category !== category) return false;
    if (spaceId !== "" && device.spaceId !== spaceId) return false;
    return matchesOnline(device, online);
  });

  renderDeviceRows(filtered, loadedSpaces);

  devicesView.summary.textContent =
    `当前显示 ${filtered.length} 台 / 全部 ${loadedDevices.length} 台`;

  const isEmpty = filtered.length === 0;
  devicesView.table.hidden = isEmpty;
  devicesView.emptyNote.hidden = !isEmpty;
}

function fillSpaceOptions(spaces) {
  if (!devicesView) return;

  const select = devicesView.spaceSelect;
  const current = select.value;

  select.replaceChildren();

  const allOption = document.createElement("option");
  allOption.value = "";
  allOption.textContent = "全部空间";
  select.append(allOption);

  for (const space of spaces) {
    const option = document.createElement("option");
    option.value = space.id;
    option.textContent = space.name;
    select.append(option);
  }

  // 重新载入时保留仍然有效的空间选择。
  select.value = spaces.some((space) => space.id === current) ? current : "";
}

// 清空搜索与三个下拉框；数据尚未读取时只复位控件，避免出现 0 台。
function resetDeviceFilters() {
  if (!devicesView) return;

  devicesView.searchInput.value = "";
  devicesView.categorySelect.value = "";
  devicesView.spaceSelect.value = "";
  devicesView.onlineSelect.value = "";

  if (devicesLoaded) {
    applyDeviceFilters();
  }
}

async function loadDevices() {
  if (!devicesView || devicesLoading) return;

  devicesLoading = true;
  setDevicesStatus("正在读取设备");

  try {
    const [devices, spaces, overview] = await Promise.all([
      getDevices(),
      getSpaces(),
      getOverview(),
    ]);

    loadedDevices = devices;
    loadedSpaces = spaces;
    loadedPoints = overview.points;

    if (devices.length === 0) {
      setDevicesStatus("没有设备");
      devicesLoaded = true;
      return;
    }

    fillSpaceOptions(spaces);
    applyDeviceFilters();

    devicesView.status.hidden = true;
    devicesView.wrap.hidden = false;
    devicesView.errorBox.hidden = true;
    devicesLoaded = true;
  } catch (error) {
    showDevicesError(error);
    console.error("设备数据读取失败", error);
  } finally {
    devicesLoading = false;
  }
}

// ---------- 空间读取 ----------

function setSpacesStatus(text) {
  if (!spacesView) return;
  spacesView.status.textContent = text;
  spacesView.status.hidden = false;
  spacesView.grid.hidden = true;
  spacesView.errorBox.hidden = true;
}

function showSpacesError(error) {
  if (!spacesView) return;
  const detail =
    error instanceof Error && error.message ? error.message : "未知错误";
  spacesView.status.hidden = true;
  spacesView.grid.hidden = true;
  spacesView.errorBox.hidden = false;
  spacesView.errorText.textContent = `空间读取失败：${detail}`;
}

// 设备按 spaceId 归属，数量从已读取的设备数组逐台累计，不写死。
function countDevicesBySpace(devices) {
  const counts = new Map();
  for (const device of devices) {
    if (!device || typeof device.spaceId !== "string") continue;
    counts.set(device.spaceId, (counts.get(device.spaceId) ?? 0) + 1);
  }
  return counts;
}

// 表单字段：标签包住输入框，供空间位置编辑复用。
function createSpaceField(labelText, inputId, value) {
  const field = document.createElement("label");
  field.className = "space-form-field";

  const caption = document.createElement("span");
  caption.className = "space-form-label";
  caption.textContent = labelText;

  const input = document.createElement("input");
  input.type = "text";
  input.id = inputId;
  input.className = "filter-control";
  input.value = value ?? "";
  input.autocomplete = "off";

  field.append(caption, input);
  return { field, input };
}

// 按数据原始顺序展示空间，每张卡片显示名称、楼栋、楼层和设备数量。
function renderSpaceCards(spaces, devices) {
  if (!spacesView) return;

  const counts = countDevicesBySpace(devices);
  const grid = spacesView.grid;
  grid.replaceChildren();
  activeSpaceEditor = null;

  for (const space of spaces) {
    const card = document.createElement("article");
    card.className = "space-card";

    const name = document.createElement("h3");
    name.textContent = space.name;

    const facts = document.createElement("dl");
    facts.className = "space-facts";

    const buildingTerm = document.createElement("dt");
    buildingTerm.textContent = "楼栋";
    const buildingValue = document.createElement("dd");
    buildingValue.textContent = space.building ?? "未知";

    const floorTerm = document.createElement("dt");
    floorTerm.textContent = "楼层";
    const floorValue = document.createElement("dd");
    floorValue.textContent = space.floor ?? "未知";

    facts.append(buildingTerm, buildingValue, floorTerm, floorValue);

    const count = document.createElement("p");
    count.className = "space-count";
    count.textContent = `设备 ${counts.get(space.id) ?? 0} 台`;

    const actions = document.createElement("div");
    actions.className = "space-actions";

    const viewButton = document.createElement("button");
    viewButton.type = "button";
    viewButton.className = "space-action";
    viewButton.textContent = "查看设备";
    viewButton.setAttribute("aria-label", `查看${space.name}的设备`);
    viewButton.addEventListener("click", () => {
      openDevicesForSpace(space.id);
    });

    const editButton = document.createElement("button");
    editButton.type = "button";
    editButton.className = "space-action is-secondary";
    editButton.textContent = "编辑位置";
    editButton.setAttribute("aria-label", `编辑${space.name}的位置`);
    editButton.setAttribute("aria-expanded", "false");
    editButton.setAttribute("aria-controls", `space-editor-${space.id}`);

    actions.append(viewButton, editButton);

    // 编辑表单只含楼栋、楼层；空间名称只读展示，ID 与设备归属不参与修改。
    const form = document.createElement("form");
    form.className = "space-form";
    form.id = `space-editor-${space.id}`;
    form.hidden = true;

    const formName = document.createElement("p");
    formName.className = "space-form-name";
    formName.textContent = `空间：${space.name}`;

    const buildingField = createSpaceField(
      "楼栋",
      `space-building-${space.id}`,
      space.building
    );
    const floorField = createSpaceField(
      "楼层",
      `space-floor-${space.id}`,
      space.floor
    );

    const errorText = document.createElement("p");
    errorText.className = "space-form-error";
    errorText.setAttribute("role", "alert");
    errorText.hidden = true;

    const formActions = document.createElement("div");
    formActions.className = "space-form-actions";

    const saveButton = document.createElement("button");
    saveButton.type = "submit";
    saveButton.className = "space-save";
    saveButton.textContent = "保存";

    const cancelButton = document.createElement("button");
    cancelButton.type = "button";
    cancelButton.className = "space-cancel";
    cancelButton.textContent = "取消";

    formActions.append(saveButton, cancelButton);
    form.append(
      formName,
      buildingField.field,
      floorField.field,
      errorText,
      formActions
    );

    function closeEditor() {
      form.hidden = true;
      editButton.setAttribute("aria-expanded", "false");
      errorText.hidden = true;
      errorText.textContent = "";
      buildingField.input.value = space.building ?? "";
      floorField.input.value = space.floor ?? "";
      if (activeSpaceEditor && activeSpaceEditor.form === form) {
        activeSpaceEditor = null;
      }
    }

    let saving = false;

    editButton.addEventListener("click", () => {
      if (!form.hidden) {
        closeEditor();
        return;
      }

      if (activeSpaceEditor && activeSpaceEditor.form !== form) {
        activeSpaceEditor.close();
      }

      buildingField.input.value = space.building ?? "";
      floorField.input.value = space.floor ?? "";
      errorText.hidden = true;
      errorText.textContent = "";
      form.hidden = false;
      editButton.setAttribute("aria-expanded", "true");
      activeSpaceEditor = { form, close: closeEditor };
      buildingField.input.focus();
    });

    cancelButton.addEventListener("click", () => {
      closeEditor();
      editButton.focus();
    });

    form.addEventListener("submit", async (event) => {
      event.preventDefault();
      if (saving) return;

      saving = true;
      saveButton.disabled = true;
      cancelButton.disabled = true;
      saveButton.textContent = "正在保存";
      errorText.hidden = true;

      try {
        await saveSpace(space.id, {
          building: buildingField.input.value,
          floor: floorField.input.value,
        });

        // 保存成功后重新读取空间，用返回后的数据展示，不自行拼改页面。
        await loadSpaces();
      } catch (error) {
        // 失败时保留输入内容和表单，方便学生直接修改后重试。
        errorText.textContent = `保存失败：${describeError(error)}`;
        errorText.hidden = false;
        form.hidden = false;
        editButton.setAttribute("aria-expanded", "true");
      } finally {
        saving = false;
        saveButton.disabled = false;
        cancelButton.disabled = false;
        saveButton.textContent = "保存";
      }
    });

    card.append(name, facts, count, actions, form);
    grid.append(card);
  }
}

async function loadSpaces() {
  if (!spacesView || spacesLoading) return;

  spacesLoading = true;
  setSpacesStatus("正在读取空间");

  try {
    const [spaces, devices] = await Promise.all([getSpaces(), getDevices()]);

    if (spaces.length === 0) {
      setSpacesStatus("没有空间");
      spacesLoaded = true;
      return;
    }

    renderSpaceCards(spaces, devices);

    // 设备表共用同一份空间数据；已加载时同步名称与筛选下拉框。
    loadedSpaces = spaces;
    if (devicesView && devicesLoaded) {
      fillSpaceOptions(spaces);
      applyDeviceFilters();
    }

    spacesView.status.hidden = true;
    spacesView.grid.hidden = false;
    spacesView.errorBox.hidden = true;
    spacesLoaded = true;
  } catch (error) {
    showSpacesError(error);
    console.error("空间数据读取失败", error);
  } finally {
    spacesLoading = false;
  }
}

// 进入现有设备页：清空搜索、类型、在线情况，只保留本次点击的空间筛选。
async function openDevicesForSpace(spaceId) {
  if (!devicesView) return;

  if (!devicesLoaded && !devicesLoading) {
    await loadDevices();
  }

  devicesView.searchInput.value = "";
  devicesView.categorySelect.value = "";
  devicesView.onlineSelect.value = "";

  const hasSpace = Array.from(devicesView.spaceSelect.options).some(
    (option) => option.value === spaceId
  );
  devicesView.spaceSelect.value = hasSpace ? spaceId : "";

  if (devicesLoaded) {
    applyDeviceFilters();
  }

  const devicesMenuItem = menuItems.find(
    (item) => item.dataset.view === "devices"
  );
  if (devicesMenuItem) {
    devicesMenuItem.click();
    return;
  }

  render("devices");
  window.location.hash = "devices";
}

// ---------- 概览底部说明 ----------

const STAT_TARGETS = [
  ["stat-devices", "devices"],
  ["stat-spaces", "spaces"],
  ["stat-points", "points"],
];

function setStatText(text) {
  for (const [id] of STAT_TARGETS) {
    const element = document.getElementById(id);
    if (element) element.textContent = text;
  }
}

// 卡片数值取自实际返回数组的长度，不写死。
function setStatCounts(overview) {
  for (const [id, key] of STAT_TARGETS) {
    const element = document.getElementById(id);
    if (element) element.textContent = String(overview[key].length);
  }
}

function describeError(error) {
  return error instanceof Error && error.message ? error.message : "未知错误";
}

async function showOverviewSummary() {
  const note = document.getElementById("data-note");

  setStatText("正在读取");

  try {
    const overview = await getOverview();
    setStatCounts(overview);

    if (note) {
      const deviceCount = overview.devices.length;
      const spaceCount = overview.spaces.length;
      const pointCount = overview.points.length;
      note.textContent =
        `${DATA_SOURCE_NOTE}｜设备 ${deviceCount} 台 · ` +
        `空间 ${spaceCount} 个 · 点位 ${pointCount} 个`;
    }
  } catch (error) {
    // 读取失败时明确显示，不用 0 冒充数量。
    setStatText("读取失败");
    if (note) {
      note.textContent = `${DATA_SOURCE_NOTE}｜读取失败：${describeError(error)}，请刷新页面重试`;
    }
    console.error("练习数据载入失败", error);
  }
}

showOverviewSummary();

// 校园值班台 · 数据服务（第03课第3步）
// 以 mockCampus 为起点，再合并浏览器里保存的空间位置；不请求后端。
// 演示记录统一保存在 localStorage 的 campus-v2-demo 中。
// 页面统一通过这里取业务数据，不要直接导入 mock-data.js。

import { mockCampus } from "./mock-data.js";

const STORAGE_KEY = "campus-v2-demo";

// 每次返回独立副本，调用方改动结果不会影响当前数据。
function copy(value) {
  if (typeof structuredClone === "function") {
    return structuredClone(value);
  }
  return JSON.parse(JSON.stringify(value));
}

// 演示记录的空结构；spaces、owners、cases 必须一起保存，写入时互不覆盖。
function createEmptyDemoState() {
  return { spaces: [], owners: [], cases: [] };
}

// 读取整个演示记录对象。记录不存在时返回空结构，不代表要立刻写入。
// JSON 损坏或存储被禁止时抛出明确错误，绝不返回空结构覆盖原记录。
function readSavedDemoState() {
  let raw;

  try {
    raw = window.localStorage.getItem(STORAGE_KEY);
  } catch (error) {
    throw new Error("浏览器禁止访问本地存储，无法读取演示记录");
  }

  if (raw === null) {
    return createEmptyDemoState();
  }

  let parsed;
  try {
    parsed = JSON.parse(raw);
  } catch (error) {
    throw new Error("浏览器中的演示记录已损坏（JSON 无效），未加载也未覆盖");
  }

  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("浏览器中的演示记录格式不正确，未加载也未覆盖");
  }

  const spaces = parsed.spaces === undefined ? [] : parsed.spaces;
  const owners = parsed.owners === undefined ? [] : parsed.owners;
  const cases = parsed.cases === undefined ? [] : parsed.cases;

  if (
    !Array.isArray(spaces) ||
    !Array.isArray(owners) ||
    !Array.isArray(cases)
  ) {
    throw new Error(
      "浏览器中的演示记录缺少 spaces、owners、cases 数组，未加载也未覆盖"
    );
  }

  return { ...parsed, spaces, owners, cases };
}

function writeSavedDemoState(state) {
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
  } catch (error) {
    throw new Error("浏览器禁止保存或存储空间不足，本次修改未保存");
  }
}

// 只合并已保存的楼栋、楼层，空间名称和 ID 始终以 mockCampus 为准。
function mergeSavedSpaceLocations(baseSpaces, savedSpaces) {
  const savedById = new Map();

  for (const entry of savedSpaces) {
    if (!entry || typeof entry !== "object" || typeof entry.id !== "string") {
      continue;
    }
    savedById.set(entry.id, entry);
  }

  return baseSpaces.map((space) => {
    const saved = savedById.get(space.id);
    if (!saved) return space;

    const building =
      typeof saved.building === "string" ? saved.building.trim() : "";
    const floor = typeof saved.floor === "string" ? saved.floor.trim() : "";

    return {
      ...space,
      building: building === "" ? space.building : building,
      floor: floor === "" ? space.floor : floor,
    };
  });
}

// 当前空间数据：先复制原始练习数据，再合并浏览器中保存的位置。
let currentSpaces = null;
let spacesLoadError = null;

function getCurrentSpaces() {
  if (currentSpaces) return currentSpaces;
  if (spacesLoadError) throw spacesLoadError;

  try {
    const saved = readSavedDemoState();
    currentSpaces = mergeSavedSpaceLocations(
      copy(mockCampus.spaces),
      saved.spaces
    );
    return currentSpaces;
  } catch (error) {
    spacesLoadError = error;
    throw error;
  }
}

// 概览：与后端 /api/overview 的约定保持一致，返回五项完整练习数据。
export async function getOverview() {
  return {
    spaces: copy(getCurrentSpaces()),
    devices: copy(mockCampus.devices),
    points: copy(mockCampus.points),
    history: copy(mockCampus.history),
    alarms: copy(mockCampus.alarms),
  };
}

export async function getDevices() {
  return copy(mockCampus.devices);
}

export async function getSpaces() {
  return copy(getCurrentSpaces());
}

// 只修改楼栋和楼层；空间 ID、设备及其归属都不在这里改动。
// 先写浏览器存储，成功后才更新当前数据；失败时保留原记录和页面输入。
export async function saveSpace(id, { building, floor } = {}) {
  const space = getCurrentSpaces().find((item) => item.id === id);
  if (!space) {
    throw new Error("找不到该空间");
  }

  const nextBuilding = typeof building === "string" ? building.trim() : "";
  const nextFloor = typeof floor === "string" ? floor.trim() : "";

  if (nextBuilding === "") {
    throw new Error("楼栋不能为空");
  }
  if (nextFloor === "") {
    throw new Error("楼层不能为空");
  }

  // 读取已有记录，保留其中的 owners 和 cases，只替换 spaces 的位置。
  const saved = readSavedDemoState();

  const nextSpaces = getCurrentSpaces().map((item) => ({
    id: item.id,
    name: item.name,
    building: item.id === id ? nextBuilding : item.building,
    floor: item.id === id ? nextFloor : item.floor,
  }));

  writeSavedDemoState({
    ...saved,
    spaces: nextSpaces,
    owners: saved.owners,
    cases: saved.cases,
  });

  space.building = nextBuilding;
  space.floor = nextFloor;

  return copy(space);
}

